// FindPage reads a page of the Ticket rows filter finds (D60, amended), in
// opts.Sort's order, ties broken by id in the same direction: up to
// opts.Limit rows after opts.After, and Next when more follow. It runs one
// query of opts.Limit + 1 rows and no count. A key is a row's id alone:
// in an order by a sort field, the query reads the key's row for its value,
// soft-deleted or not and whatever the filter, so a row the filter no longer
// finds still places the page. An After that holds no id, or whose row
// no longer exists in an order by a sort field, is ErrPageKey. A key of another
// order cannot be told from one of this order: the router refuses a cursor
// of another sort before FindPage reads it.
func (r *TicketRepository) FindPage(ctx context.Context, filter *TicketFilter, opts *TicketPageOptions) (*TicketPage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Ticket rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = TicketSortById
	}
	column, ok := ticketSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Ticket sorts by id, title and status, not %q", string(field))
	}
	byKey := field == TicketSortById

	// Next is the key of the page's last row, so the page reads its primary
	// key whatever Fields selects.
	fieldStrings := ticketFieldStrings(opts.Fields)
	if !containsString(fieldStrings, "id") {
		fieldStrings = append(fieldStrings, "id")
	}
	if err := validateFields(fieldStrings, TicketAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "ticket")
	// The filter's conditions, each qualified by the table, then the
	// keyset's.
	var args []interface{}
	conditions := filter.conditions(&args, 0)
	comparison, direction := ">", "ASC"
	if opts.Sort.Desc {
		comparison, direction = "<", "DESC"
	}
	var key any
	if opts.After != nil {
		var err error
		if key, err = opts.After.arg(); err != nil {
			return nil, err
		}
		args = append(args, key)
		placeholder := fmt.Sprintf("$%d", len(args))
		if byKey {
			conditions = append(conditions, fmt.Sprintf(`ticket.id %s %s`, comparison, placeholder))
		} else {
			// The key's row gives the sort field's value: no deleted_at
			// condition and no filter, so a row soft-deleted or changed
			// since the page before still places this one.
			conditions = append(conditions, fmt.Sprintf(`(%s, ticket.id) %s ((SELECT %s FROM ticket AS page_key WHERE page_key.id = %s), %s)`,
				column.sql, comparison, column.key, placeholder, placeholder))
		}
	}
	whereClause := ""
	if len(conditions) > 0 {
		whereClause = " WHERE " + strings.Join(conditions, " AND ")
	}
	orderByClause := fmt.Sprintf(" ORDER BY %s %s", column.sql, direction)
	if !byKey {
		orderByClause += fmt.Sprintf(`, ticket.id %s`, direction)
	}
	query := fmt.Sprintf(`SELECT %s FROM ticket%s%s LIMIT %d`, selectFields, whereClause, orderByClause, limit+1)

	rows, err := r.findRows(ctx, "FindPage", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 && opts.After != nil && !byKey {
		// A key whose row no longer exists places no row: its value is
		// null, which no row comes after. Only then is the page empty
		// without being the last.
		if err := r.pageKeyExists(ctx, key); err != nil {
			return nil, err
		}
	}
	page := &TicketPage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = ticketPageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// pageKeyExists is nil when the table holds a row whose primary key is key,
// soft-deleted or not, and ErrPageKey when it holds none.
func (r *TicketRepository) pageKeyExists(ctx context.Context, key any) error {
	query := `SELECT EXISTS (SELECT 1 FROM ticket WHERE ticket.id = $1)`
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, key)
	} else {
		row = r.db.pool.QueryRow(ctx, query, key)
	}
	var exists bool
	if err := row.Scan(&exists); err != nil {
		return fmt.Errorf("failed to read the page key's row: %w", err)
	}
	if !exists {
		return fmt.Errorf("%w: no Ticket row has the key's id", ErrPageKey)
	}
	return nil
}

// CreateOne inserts a new Ticket row through the behaviors' core (D103), in a
// transaction: each behavior's create initializes the fields it owns, and the
// row is read back. A refusal of the core's is returned as the *rules.Refusal
// it is.
func (r *TicketRepository) CreateOne(ctx context.Context, input *TicketCreate) (*types.Ticket, error) {
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Ticket, error) {
		return (&TicketRepository{tx: tx, txDB: r.database()}).createThroughCore(ctx, input)
	})
}

// ticketUniqueKeys are the conflict targets of Ticket's unique keys, and
// the assignment an upsert that sets nothing writes, so the row it
// conflicts with is returned (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert only if changed reads back, empty for a
// key over an expression, and the key's columns as a batch insert's cells
// name them (D89).
var ticketUniqueKeys = map[TicketUniqueKey]struct {
	conflict, keep, rows string
	columns              []string
}{
	TicketUniqueById: {`(id)`, `id = EXCLUDED.id`, `SELECT "id", "title", "visit_at", "status", "status_entered_at", "_version" FROM ticket WHERE (id) IN (%s)`, []string{`id`}},
}

// ticketKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func ticketKeyOf(on TicketUniqueKey, row *types.Ticket) (string, bool) {
	switch on {
	case TicketUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	}
	return "", false
}

// database is the Database the repository runs on.
func (r *TicketRepository) database() *Database {
	if r.txDB != nil {
		return r.txDB
	}
	return r.db
}

// scanReturned scans a row of every column of Ticket, as a write returns
// it, and, with inserted, the flag an upsert returns after them (D89).
func (r *TicketRepository) scanReturned(row pgx.Row, inserted *bool) (*types.Ticket, error) {
	result := &types.Ticket{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempVisitAt *types.TemporalDateTime
	var tempStatusEnteredAt *types.TemporalDateTime

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	// Scan all fields in schema order (matches DDL column order)
	dest := []any{

		&result.Id,

		&result.Title,

		&tempVisitAt,

		&result.Status,

		&tempStatusEnteredAt,

		&result.Version,
	}
	if inserted != nil {
		dest = append(dest, inserted)
	}
	if err := row.Scan(dest...); err != nil {
		return nil, err
	}

	// Copy nullable fields when present

	if tempVisitAt != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.VisitAt = tempVisitAt
	}
	if tempStatusEnteredAt != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.StatusEnteredAt = tempStatusEnteredAt
	}

	// Set relationship IDs from scanned FK values

	return result, nil
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, only if changed, and the second
// statement of an encrypted field.
func (r *TicketRepository) upsertRow(ctx context.Context, input *types.Ticket, on TicketUniqueKey, update *TicketUpdate, onlyIfChanged bool) (*UpsertResult[*types.Ticket], error) {
	key := ticketUniqueKeys[on]
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := ticketUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: title
	fields = append(fields, `title`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Title)
	// Optional field: visitAt - only add if set
	{
		if input.VisitAt != nil {
			fields = append(fields, `visit_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.VisitAt))
		}
	}
	// Required field: status
	fields = append(fields, `status`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Status)
	// Optional field: statusEnteredAt - only add if set
	{
		if input.StatusEnteredAt != nil {
			fields = append(fields, `status_entered_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.StatusEnteredAt))
		}
	}

	// Handle relationship foreign key columns

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses, compareCurrent, compareNext []string
	if update.Title != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`title = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `ticket.title`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Title)
	}
	if update.VisitAt != nil && update.VisitAtSetNull {
		return nil, fmt.Errorf("visit_at cannot be updated with both value and null assignment")
	}
	if update.VisitAtSetNull {
		setClauses = append(setClauses, `visit_at = NULL`)
		compareCurrent = append(compareCurrent, `ticket.visit_at`)
		compareNext = append(compareNext, `NULL`)
	} else if update.VisitAt != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`visit_at = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `ticket.visit_at`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, time.Time(*update.VisitAt))
	}

	assigned := len(setClauses)
	if assigned == 0 {
		// An update that sets no field leaves the row as it is, stamps and
		// all, and returns it.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at

		// Set updated_by

	}

	query := fmt.Sprintf(
		`INSERT INTO ticket (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "title", "visit_at", "status", "status_entered_at", "_version", (xmax = 0) AS _inserted`,
		strings.Join(fields, ", "),
		"("+strings.Join(placeholders, ", ")+")",
		key.conflict,
		strings.Join(setClauses, ", "),
		upsertWhere(``, compareCurrent, compareNext, onlyIfChanged),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}
	var inserted bool
	scanned, err := r.scanReturned(row, &inserted)
	var upserted *UpsertResult[*types.Ticket]
	switch {
	case err == nil:
		status := UpsertUnchanged
		if inserted {
			status = UpsertInserted
		} else if assigned > 0 {
			status = UpsertUpdated
		}
		upserted = &UpsertResult[*types.Ticket]{Row: scanned, Status: status}
	case err != pgx.ErrNoRows:
		return nil, fmt.Errorf("failed to scan result: %w", err)
	case !onlyIfChanged:
		// The row the key conflicts with is soft-deleted.
		return nil, ErrNotFound
	default:
		// The row the key conflicts with already held the update's values.
		keyValues, ok := upsertCellValues(upsertCells(fields, values), key.columns)
		if !ok {
			return nil, fmt.Errorf("no Ticket row holds an unset %s: %w", string(on), ErrNotFound)
		}
		found, err := r.rowsOfKeys(ctx, on, [][]any{keyValues}, []*types.Ticket{input})
		if err != nil {
			return nil, err
		}
		upserted = &UpsertResult[*types.Ticket]{Row: found[0], Status: UpsertUnchanged}
	}
	return upserted, nil
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// only if changed, and the second statement of each encrypted field.
func (r *TicketRepository) upsertBatches(ctx context.Context, inputs []*types.Ticket, on TicketUniqueKey, update TicketFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.Ticket], error) {
	key := ticketUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.Title {
		setClauses = append(setClauses, `title = EXCLUDED.title`)
		compareCurrent = append(compareCurrent, `ticket.title`)
		compareNext = append(compareNext, `EXCLUDED.title`)
	}
	if update.VisitAt {
		setClauses = append(setClauses, `visit_at = EXCLUDED.visit_at`)
		compareCurrent = append(compareCurrent, `ticket.visit_at`)
		compareNext = append(compareNext, `EXCLUDED.visit_at`)
	}

	results := make([]UpsertResult[*types.Ticket], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := ticketUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Required field: title
			{
				cell := batchInsertCell{column: `title`, set: true}
				cell.value = input.Title
				row = append(row, cell)
			}
			// Optional field: visitAt
			{
				cell := batchInsertCell{column: `visit_at`}
				if input.VisitAt != nil {
					cell.value = time.Time(*input.VisitAt)
					cell.set = true
				}
				row = append(row, cell)
			}
			// Required field: status
			{
				cell := batchInsertCell{column: `status`, set: true}
				cell.value = input.Status
				row = append(row, cell)
			}
			// Optional field: statusEnteredAt
			{
				cell := batchInsertCell{column: `status_entered_at`}
				if input.StatusEnteredAt != nil {
					cell.value = time.Time(*input.StatusEnteredAt)
					cell.set = true
				}
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field leaves each row as it is.
			assignments = append(assignments, key.keep)
		} else {
		}
		query := fmt.Sprintf(
			`INSERT INTO ticket (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "title", "visit_at", "status", "status_entered_at", "_version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(``, compareCurrent, compareNext, onlyIfChanged),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = ticketKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.Ticket], len(prepared))
		for n, row := range returned {
			text, ok := ticketKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of Ticket wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.Ticket]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, only if changed,
		// which it reads back by its key, or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged {
				return nil, fmt.Errorf("the Ticket row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.Ticket, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no Ticket row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.Ticket]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *TicketRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.Ticket, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.Ticket
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert only if changed left as they were
// (D89). A key no live row holds is ErrNotFound.
func (r *TicketRepository) rowsOfKeys(ctx context.Context, on TicketUniqueKey, keys [][]any, inputs []*types.Ticket) ([]*types.Ticket, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(ticketUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.Ticket{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := ticketKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.Ticket, len(inputs))
	for i, input := range inputs {
		text, _ := ticketKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the Ticket row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// CreateMany inserts multiple Ticket rows, each a create of the behaviors'
// core (D103), in order, in one transaction.
func (r *TicketRepository) CreateMany(ctx context.Context, inputs []*TicketCreate) ([]*types.Ticket, error) {
	if len(inputs) == 0 {
		return []*types.Ticket{}, nil
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]*types.Ticket, error) {
		repo := &TicketRepository{tx: tx, txDB: r.database()}
		rows := make([]*types.Ticket, 0, len(inputs))
		for _, input := range inputs {
			row, err := repo.createThroughCore(ctx, input)
			if err != nil {
				return nil, err
			}
			rows = append(rows, row)
		}
		return rows, nil
	})
}

// UpdateOne updates a single Ticket row by ID through the behaviors' core
// (D103), in a transaction: the own fields update sets, which holds no field
// a behavior owns, and the row is read back. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *TicketRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *TicketUpdate) (*types.Ticket, error) {
	if update == nil {
		update = &TicketUpdate{}
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Ticket, error) {
		repo := &TicketRepository{tx: tx, txDB: r.database()}
		patch := repo.corePatch(update)
		columns, err := repo.updateColumns(ctx, update)
		if err != nil {
			return nil, err
		}
		if len(patch) == 0 && len(columns) == 0 {
			return nil, fmt.Errorf("no fields to update")
		}
		if err := rules.RunUpdate(ctx, rulesHost(tx), "Ticket", id.String(), patch, behaviorCaller(ctx), &rules.ExecuteOptions{OwnColumns: columns}); err != nil {
			return nil, behaviorNotFound(err, "Ticket", id)
		}
		return repo.GetOne(ctx, id, nil)
	})
}

// UpdateMany updates multiple Ticket records matching the filter
func (r *TicketRepository) UpdateMany(ctx context.Context, filter *TicketFilter, update *TicketUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Title != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`title = $%d`, paramNum))
		values = append(values, *update.Title)
	}
	if update.VisitAt != nil && update.VisitAtSetNull {
		return 0, fmt.Errorf("visit_at cannot be updated with both value and null assignment")
	}
	if update.VisitAtSetNull {
		setClauses = append(setClauses, `visit_at = NULL`)
	} else if update.VisitAt != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`visit_at = $%d`, paramNum))
		values = append(values, time.Time(*update.VisitAt))
	}

	// Set updated_at

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)

	query := fmt.Sprintf(
		`UPDATE ticket SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne permanently deletes a single Ticket row by ID through the
// behaviors' core (D103), in a transaction. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *TicketRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	_, err := inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (struct{}, error) {
		opts := &rules.ExecuteOptions{}
		if err := rules.RunDelete(ctx, rulesHost(tx), "Ticket", id.String(), behaviorCaller(ctx), opts); err != nil {
			return struct{}{}, behaviorNotFound(err, "Ticket", id)
		}
		return struct{}{}, nil
	})
	return err
}

// DeleteMany permanently deletes multiple Ticket records matching the filter
func (r *TicketRepository) DeleteMany(ctx context.Context, filter *TicketFilter) (int, error) {
	// Build WHERE clause
	var values []interface{}
	whereClause := filter.buildWhereClause(&values, 0)

	query := fmt.Sprintf(`DELETE FROM ticket%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}
